"""
HISTORICAL since the neighbourhood start was adopted (M187 decided): the setting start_mode no longer exists, so this runs the one behaviour. The measurement (full stance selection both ways) was made before: data/checker_start/20261026_142253.

    MUJOCO_GL=egl python experiments/checker_start_compare.py --layout normal|moved --mode today|neighbourhood --out data/checker_start/<name>

The same steps as src/stance_select.apply_stance_selection (the context, the full check, select_bench_stance on the plan "navigate to the beaker, pick it up, navigate to the hotplate, place it"), but the
full check is kept so that its `start_log` (one entry per solved stop: how it was started, whether it passed, whether a random rescue was used or would have been possible) can be saved after every
check. Writes <out>/result.json: the chosen stance and place angle, the selection time, every full check call (stance, verdict, place window, seconds) with its start log.
"""

import argparse
import copy
import json
import os
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src import bench_stance as bs  # noqa: E402
from src.full_check import FullCheck  # noqa: E402
from src.mpvi_postprocess import postprocess  # noqa: E402
from src.stance_select import make_context, select_bench_stance  # noqa: E402
from src.task_config import BENCH_STANCE_CFG, FULLCHECK_CFG, TASK_CFG  # noqa: E402
from src.world_model import StaticTaskSource, WorldModel  # noqa: E402
from stance_select_moved_test import MOVED  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402


def main(args):
    task_cfg = MOVED if args.layout == "moved" else TASK_CFG
    cfg = copy.deepcopy(BENCH_STANCE_CFG)
    quiet = lambda *_: None
    maps = bs.load_maps("data/reach_map", sides=(cfg["arm"],))
    fc = FullCheck(maps={**bs.load_maps("data/reach_map")}, task_cfg=task_cfg)
    fc.cfg = {**FULLCHECK_CFG}                               # the neighbourhood start is the only behaviour since M187 was decided; --mode is kept only to name the output
    ctx = make_context(fc.model, fc.scene_data, maps, task_cfg, cfg, chk=fc.chk, say=quiet)
    world = WorldModel([StaticTaskSource(task_cfg)])
    world.refresh(0.0)
    tagged = postprocess(PLAN4, False, say=quiet)
    calls = []
    check0 = fc.check

    def check(stance, points, *a, **k):
        t0 = time.perf_counter()
        r = check0(stance, points, *a, **k)
        calls.append({"stance": [float(v) for v in stance], "ok": bool(r["ok"]), "failed": list(r.get("failed", [])), "reason": str(r.get("reason", ""))[:300], "seconds": time.perf_counter() - t0,
                      "place": r.get("place"), "start_log": list(fc.start_log), "cached": bool(r.get("cached"))})
        return r
    fc.check = check
    t0 = time.perf_counter()
    sel = select_bench_stance(tagged, world, task_cfg, ctx, cfg, full_check=fc, say=print)
    secs = time.perf_counter() - t0
    run = sel["report"]["runs"][0] if sel["report"]["runs"] else None
    res = {"layout": args.layout, "mode": args.mode, "ok": sel["ok"], "stop": sel["stop"], "selection_seconds": secs,
           "chosen_stance": None if run is None else {"xy": [float(v) for v in run["stance"]["xy"]], "q": float(run["stance"]["q"])}, "place_theta_deg": None if run is None else run.get("place_theta_deg"),
           "calls": calls}
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    tmp = out / "result.json.tmp"
    tmp.write_text(json.dumps(res, indent=1, default=str))
    tmp.replace(out / "result.json")
    n_log = sum(len(c["start_log"]) for c in calls)
    print(f"{args.layout} {args.mode}: ok {sel['ok']}, chosen {res['chosen_stance']}, theta {res['place_theta_deg']}, {secs:.1f} s, {len(calls)} full checks, {n_log} stops logged", flush=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--layout", choices=("normal", "moved"), default="normal")
    ap.add_argument("--mode", choices=("today", "neighbourhood"), default="today")
    ap.add_argument("--out", required=True)
    main(ap.parse_args())
